   /**
    * Creates the provided command.
    * 
    * @param		command ${class.getCreateCommandAlias()}
    * @exception    ProcessingException
    * @exception	IllegalArgumentException
    * @return		Forecast
    */
	public Forecast createForecast( CreateForecastCommand command )
    throws ProcessingException, IllegalArgumentException {

		Forecast entity = new Forecast();

		try {
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	ForecastValidator.getInstance().validate( command );    

            entity.setForecastId( command.getForecastId() );
            entity.setName( command.getName() );
            entity.setHorizon( command.getHorizon() );
            entity.setGranularity( command.getGranularity() );
    	    
        	// ------------------------------------------
        	// persist a new one
        	// ------------------------------------------ 
    	    entity = projector.create(entity);
    	    
			LOGGER.info( "done creating of Forecast {0} ", entity.toString() );

        }
        catch (Exception exc) {
            final String errMsg = "Unable to create Forecast - " + exc;
            LOGGER.warn(  errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }

   /**
    * Update the provided command.
    * @param		command UpdateForecastCommand
    * @exception    ProcessingException
    * @exception  	IllegalArgumentException
    * @return		Forecast
    */
    public Forecast updateForecast( UpdateForecastCommand command ) 
    throws ProcessingException, IllegalArgumentException {

	    Forecast entity = new Forecast();

    	try {       

			// --------------------------------------
        	// validate 
        	// --------------------------------------    	
        	ForecastValidator.getInstance().validate( command );    

            entity.setForecastId( command.getForecastId() );
            entity.setName( command.getName() );
            entity.setHorizon( command.getHorizon() );
            entity.setModelVersion( command.getModelVersion() );
            entity.setTimeSeries( command.getTimeSeries() );
            entity.setDatasets( command.getDatasets() );
            entity.setGranularity( command.getGranularity() );
        	
        	// ------------------------------------------
        	// persist an existing one
        	// ------------------------------------------ 
        	entity = projector.update(entity);
    	    
			LOGGER.info( "done saving of Forecast {0} ", entity.toString() );
    	}
        catch (Exception exc) {
            final String errMsg = "Unable to save Forecast - " + exc;
            LOGGER.warn( errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
    	
    	return entity;
    }
   
